OLDFENCE = re.compile(r'(OLD(?: \d)? \(exact\):\n~~~~\n.*?\n~~~~)', re.S)
def smart(text, old, new):
    segs = OLDFENCE.split(text)
    return ''.join(s if OLDFENCE.fullmatch(s) else s.replace(old, new) for s in segs)
